import { Component, Inject, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatDialogModule, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { ChatRequestData } from '../../models/community.model';
import { NotificationService } from '../../../../shared/services/notification.service';

@Component({
  selector: 'app-chat-request',
  standalone: true,
  imports: [CommonModule, FormsModule, MatDialogModule],
  templateUrl: './chat-request.component.html',
  styleUrls: ['./chat-request.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ChatRequestComponent {
  message = '';

  constructor(
    private dialogRef: MatDialogRef<ChatRequestComponent>,
    @Inject(MAT_DIALOG_DATA) public data: ChatRequestData,
    private notification: NotificationService,
  ) {}

  get contextLabel(): string {
    switch (this.data.type) {
      case 'member':
        return 'メンバーへのチャットリクエスト';
      case 'recruitment':
        return '募集への応募';
      case 'appeal':
        return 'アピールへの興味あり';
      default:
        return 'チャットリクエスト';
    }
  }

  onCancel(): void {
    this.dialogRef.close();
  }

  onSend(): void {
    this.dialogRef.close({ message: this.message });
    this.notification.success('チャットリクエストを送信しました');
  }
}
