import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy, OnInit, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Recruitment } from '../../models/community.model';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { MatIconModule } from '@angular/material/icon';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';

@Component({
  selector: 'app-recruitment-detail',
  standalone: true,
  imports: [CommonModule, MatIconModule, AvatarComponent, RelativeTimePipe],
  templateUrl: './recruitment-detail.component.html',
  styleUrls: ['./recruitment-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RecruitmentDetailComponent implements OnInit, OnChanges {
  @Input() recruitment!: Recruitment;
  @Input() isMember = false;
  @Output() back = new EventEmitter<void>();
  @Output() apply = new EventEmitter<Recruitment>();

  mainImage: string | null = null;
  subImages: string[] = [];
  galleryOffset = 0;
  lightboxImage: string | null = null;

  ngOnInit(): void {
    this.setupImages();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['recruitment']) {
      this.setupImages();
    }
  }

  private setupImages(): void {
    const urls = this.recruitment.imageUrls || (this.recruitment.imageUrl ? [this.recruitment.imageUrl] : []);
    this.mainImage = urls.length > 0 ? urls[0] : null;
    this.subImages = urls.slice(1);
    this.galleryOffset = 0;
  }

  get canGalleryNext(): boolean {
    return this.galleryOffset < (this.subImages.length - 2) * 220;
  }

  galleryPrev(): void {
    this.galleryOffset = Math.max(0, this.galleryOffset - 220);
  }

  galleryNext(): void {
    this.galleryOffset += 220;
  }

  onGalleryClick(index: number): void {
    this.lightboxImage = this.subImages[index];
  }

  closeLightbox(): void {
    this.lightboxImage = null;
  }

  onBack(): void {
    this.back.emit();
  }

  onApply(): void {
    this.apply.emit(this.recruitment);
  }
}
