import { Component, Input, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { FormsModule } from '@angular/forms';
import { NewsItem } from '../../models/community.model';
import { CommunityService } from '../../services/community.service';
import { NewsDetailComponent } from '../news-detail/news-detail.component';

@Component({
  selector: 'app-news-list',
  standalone: true,
  imports: [CommonModule, MatIconModule, FormsModule, NewsDetailComponent],
  templateUrl: './news-list.component.html',
  styleUrls: ['./news-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class NewsListComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Input() isMember = false;

  allNews: NewsItem[] = [];
  filteredNews: NewsItem[] = [];
  pagedNews: NewsItem[] = [];
  searchTerm = '';
  selectedNewsId: string | null = null;

  currentPage = 1;
  pageSize = 10;
  totalPages = 1;

  constructor(
    private communityService: CommunityService,
    private cdr: ChangeDetectorRef,
  ) {}

  ngOnInit(): void {
    this.loadNews();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      this.loadNews();
      this.selectedNewsId = null;
    }
  }

  private loadNews(): void {
    if (this.communityId) {
      this.communityService.getNews(this.communityId).subscribe(news => {
        this.allNews = news;
        this.applyFilter();
        this.cdr.markForCheck();
      });
    }
  }

  applyFilter(): void {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) {
      this.filteredNews = [...this.allNews];
    } else {
      this.filteredNews = this.allNews.filter(n =>
        n.title.toLowerCase().includes(term) ||
        n.summary.toLowerCase().includes(term) ||
        n.source.toLowerCase().includes(term) ||
        n.category.toLowerCase().includes(term)
      );
    }
    this.currentPage = 1;
    this.updatePagination();
  }

  private updatePagination(): void {
    this.totalPages = Math.max(1, Math.ceil(this.filteredNews.length / this.pageSize));
    if (this.currentPage > this.totalPages) this.currentPage = this.totalPages;
    const start = (this.currentPage - 1) * this.pageSize;
    this.pagedNews = this.filteredNews.slice(start, start + this.pageSize);
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePagination();
  }

  get pageNumbers(): number[] {
    const maxVisible = 5;
    let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
    let end = start + maxVisible - 1;
    if (end > this.totalPages) {
      end = this.totalPages;
      start = Math.max(1, end - maxVisible + 1);
    }
    const pages: number[] = [];
    for (let i = start; i <= end; i++) pages.push(i);
    return pages;
  }

  openArticle(item: NewsItem): void {
    this.selectedNewsId = item.id;
    this.cdr.markForCheck();
  }

  onBackToList(): void {
    this.selectedNewsId = null;
    this.cdr.markForCheck();
  }

  formatDate(date: Date): string {
    const d = new Date(date);
    return `${d.getMonth() + 1}/${d.getDate()}`;
  }
}
