export interface CommunityMember {
  id: string;
  communityId: string;
  name: string;
  avatar?: string;
  company: string;
  jobTitle: string;
  joinedAt: Date;
}

export interface Recruitment {
  id: string;
  communityId: string;
  authorId: string;
  authorName: string;
  authorAvatar?: string;
  authorCompany?: string;
  authorJobTitle?: string;
  title: string;
  problem: string;
  details: string;
  imageUrl?: string;
  imageUrls?: string[];
  deadline?: Date;
  hasCompensation: boolean;
  compensationDetails?: string;
  createdAt: Date;
}

export interface Appeal {
  id: string;
  communityId: string;
  authorId: string;
  authorName: string;
  authorAvatar?: string;
  authorCompany?: string;
  authorJobTitle?: string;
  title: string;
  selfIntro: string;
  skills: string[];
  wantToMeet: string;
  imageUrl?: string;
  imageUrls?: string[];
  createdAt: Date;
}

export interface JoinRequest {
  id: string;
  communityId: string;
  userId: string;
  userName: string;
  status: 'pending' | 'approved' | 'rejected';
  createdAt: Date;
}

/** イベント参加ステータス (ユーザー指示 2026-04-21) */
export type EventRSVP = 'going' | 'maybe' | 'declined';

/** スタンプ/リアクションの種類 (ユーザー指示 2026-04-21) */
export type ReactionKind = 'like' | 'clap' | 'heart' | 'bulb' | 'laugh' | 'fire';

export interface ReactionCount {
  kind: ReactionKind;
  count: number;
  /** 現在のユーザーがこのリアクションを押しているか */
  byMe?: boolean;
}

export interface ThreadPost {
  id: string;
  communityId: string;
  authorId: string;
  authorName: string;
  authorAvatar?: string;
  authorCompany?: string;
  authorJobTitle?: string;
  title: string;
  content: string;
  imageUrl?: string;
  tags?: string[];
  votes?: number;
  createdAt: Date;
  likes: number;
  replies: number;
  /** スタンプ集計 (ユーザー指示 2026-04-21) */
  reactions?: ReactionCount[];
  /** 編集済みフラグ */
  edited?: boolean;
  editedAt?: Date;
}

export interface NewsItem {
  id: string;
  communityId: string;
  title: string;
  source: string;
  sourceUrl: string;
  imageUrl?: string;
  summary: string;
  publishedAt: Date;
  category: string;
}

export interface ThreadComment {
  id: string;
  threadId: string;
  authorId: string;
  authorName: string;
  authorAvatar?: string;
  authorCompany?: string;
  authorJobTitle?: string;
  content: string;
  createdAt: Date;
  likes: number;
  reactions?: ReactionCount[];
  edited?: boolean;
  editedAt?: Date;
}

export interface NewsComment {
  id: string;
  newsId: string;
  authorId: string;
  authorName: string;
  authorAvatar?: string;
  authorCompany?: string;
  authorJobTitle?: string;
  content: string;
  createdAt: Date;
  likes: number;
}

export interface EventParticipant {
  id: string;
  name: string;
  avatar?: string;
  /** RSVP ステータス (ユーザー指示 2026-04-21): going=参加/maybe=未定/declined=不参加 */
  rsvp?: EventRSVP;
}

export interface CommunityEvent {
  id: string;
  communityId: string;
  title: string;
  description: string;
  imageUrl?: string;
  date: Date;
  endDate?: Date;
  location: string;
  isOnline: boolean;
  meetingUrl?: string;
  organizerId: string;
  organizerName: string;
  organizerAvatar?: string;
  organizerCompany?: string;
  organizerJobTitle?: string;
  maxParticipants?: number;
  participantCount: number;
  participants: EventParticipant[];
  tags?: string[];
  createdAt: Date;
}

export type CommunityTab = 'members' | 'recruitment' | 'appeals' | 'threads' | 'news' | 'events';

export interface ChatRequestData {
  type: 'member' | 'recruitment' | 'appeal';
  targetName: string;
  prefilledInfo?: string;
  communityName: string;
}
