import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';

@Component({
  selector: 'app-blur-overlay',
  standalone: true,
  imports: [CommonModule, MatIconModule],
  templateUrl: './blur-overlay.component.html',
  styleUrls: ['./blur-overlay.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BlurOverlayComponent {
  @Input() blurred = false;
  @Input() message = 'コミュニティに参加してメンバーや募集を閲覧しましょう';
  @Output() joinRequest = new EventEmitter<void>();

  dismissed = false;

  onJoinClick(): void {
    this.joinRequest.emit();
  }

  onDismiss(): void {
    this.dismissed = true;
  }
}
