import { Component, Input, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { CommunityEvent } from '../../models/community.model';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { BlurOverlayComponent } from '../blur-overlay/blur-overlay.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { EventDetailComponent } from '../event-detail/event-detail.component';
import { EventCreateComponent } from '../event-create/event-create.component';
/* 修正 No.53 (2026-04-24): ネイティブ confirm をサイト配色のモーダルへ置換 */
import { ConfirmDialogService } from '../../../../shared/services/confirm-dialog.service';

@Component({
  selector: 'app-event-list',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, MatDialogModule, BlurOverlayComponent, AvatarComponent, EventDetailComponent],
  templateUrl: './event-list.component.html',
  styleUrls: ['./event-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventListComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Input() isMember = false;

  allEvents: CommunityEvent[] = [];
  filteredEvents: CommunityEvent[] = [];
  pagedEvents: CommunityEvent[] = [];
  searchTerm = '';

  currentPage = 1;
  pageSize = 10;
  totalPages = 1;

  selectedEvent: CommunityEvent | null = null;

  constructor(
    private communityService: CommunityService,
    private dialog: MatDialog,
    private notification: NotificationService,
    private cdr: ChangeDetectorRef,
    /* 修正 No.53 (2026-04-24) */
    private confirmDialog: ConfirmDialogService,
    /* fix (2026-04-27): ルート遷移用 */
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.loadEvents();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      this.loadEvents();
      this.selectedEvent = null;
    }
  }

  private loadEvents(): void {
    if (this.communityId) {
      this.communityService.getEvents(this.communityId).subscribe(events => {
        this.allEvents = events;
        this.applyFilter();
        this.cdr.markForCheck();
      });
    }
  }

  applyFilter(): void {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) {
      this.filteredEvents = [...this.allEvents];
    } else {
      this.filteredEvents = this.allEvents.filter(e =>
        e.title.toLowerCase().includes(term) ||
        e.description.toLowerCase().includes(term) ||
        e.location.toLowerCase().includes(term) ||
        e.organizerName.toLowerCase().includes(term) ||
        (e.tags || []).some(t => t.toLowerCase().includes(term))
      );
    }
    this.currentPage = 1;
    this.updatePagination();
  }

  private updatePagination(): void {
    this.totalPages = Math.max(1, Math.ceil(this.filteredEvents.length / this.pageSize));
    if (this.currentPage > this.totalPages) this.currentPage = this.totalPages;
    const start = (this.currentPage - 1) * this.pageSize;
    this.pagedEvents = this.filteredEvents.slice(start, start + this.pageSize);
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePagination();
  }

  get pageNumbers(): number[] {
    const maxVisible = 5;
    let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
    let end = start + maxVisible - 1;
    if (end > this.totalPages) {
      end = this.totalPages;
      start = Math.max(1, end - maxVisible + 1);
    }
    const pages: number[] = [];
    for (let i = start; i <= end; i++) pages.push(i);
    return pages;
  }

  onSelectEvent(event: CommunityEvent): void {
    this.selectedEvent = event;
  }

  onBackToList(): void {
    this.selectedEvent = null;
    this.loadEvents();
  }

  /**
   * fix (2026-04-27): SP モーダルクリック不能問題対策。
   * MatDialog → ルート遷移 (/community/:id/sub/event/create) に変更。
   */
  onCreate(): void {
    this.router.navigate(['/community', this.communityId, 'sub', 'event', 'create']);
  }

  formatMonth(date: Date): string {
    const d = new Date(date);
    return `${d.getMonth() + 1}月`;
  }

  formatDay(date: Date): string {
    const d = new Date(date);
    return `${d.getDate()}`;
  }

  formatDate(date: Date): string {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = d.getMonth() + 1;
    const day = d.getDate();
    const hours = d.getHours().toString().padStart(2, '0');
    const minutes = d.getMinutes().toString().padStart(2, '0');
    return `${year}/${month}/${day} ${hours}:${minutes}`;
  }

  isPast(date: Date): boolean {
    return new Date(date).getTime() < Date.now();
  }

  onJoinRequest(): void {
    this.communityService.requestJoin(this.communityId).subscribe(() => {
      this.isMember = true;
      this.notification.success('参加申請が承認されました');
      this.cdr.markForCheck();
    });
  }

  /** 自分が主催のイベントか (ユーザー指示 2026-04-21) */
  isMine(e: CommunityEvent): boolean {
    return this.communityService.isCurrentUser(e.organizerId);
  }

  /** 編集 */
  onEditEvent(event: CommunityEvent, ev?: Event): void {
    ev?.stopPropagation();
    const dialogRef = this.dialog.open(EventCreateComponent, {
      width: '94vw',
      maxWidth: '560px',
      maxHeight: '90dvh',
      panelClass: 'community-create-dialog',
      data: { communityId: this.communityId, editing: event },
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.loadEvents();
        this.notification.success('イベントを更新しました');
      }
    });
  }

  /** 削除 */
  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async onDeleteEvent(event: CommunityEvent, ev?: Event): Promise<void> {
    ev?.stopPropagation();
    const ok = await this.confirmDialog.confirm({
      title: 'イベントの削除',
      message: `「${event.title}」を削除してよろしいですか？`,
      confirmText: '削除',
      danger: true,
    });
    if (!ok) return;
    this.communityService.deleteEvent(event.id).subscribe(() => {
      this.loadEvents();
      this.notification.warn('イベントを削除しました');
    });
  }
}
