import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { Appeal } from '../../models/community.model';
import { BlurOverlayComponent } from '../blur-overlay/blur-overlay.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { TruncatePipe } from '../../../../shared/pipes/truncate.pipe';
import { AppealDetailComponent } from '../appeal-detail/appeal-detail.component';
import { AppealCreateComponent } from '../appeal-create/appeal-create.component';
import { ChatRequestComponent } from '../chat-request/chat-request.component';
/* 修正 No.53 (2026-04-24): ネイティブ confirm をサイト配色のモーダルへ置換 */
import { ConfirmDialogService } from '../../../../shared/services/confirm-dialog.service';

@Component({
  selector: 'app-appeal-list',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, MatDialogModule, BlurOverlayComponent, AvatarComponent, TruncatePipe, AppealDetailComponent],
  templateUrl: './appeal-list.component.html',
  styleUrls: ['./appeal-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppealListComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Input() isMember = false;
  @Output() selectAppeal = new EventEmitter<Appeal>();
  @Output() createAppeal = new EventEmitter<void>();

  allAppeals: Appeal[] = [];
  filteredAppeals: Appeal[] = [];
  pagedAppeals: Appeal[] = [];

  searchTerm = '';
  currentPage = 1;
  pageSize = 10;
  totalPages = 1;

  selectedAppeal: Appeal | null = null;

  constructor(
    private communityService: CommunityService,
    private cdr: ChangeDetectorRef,
    private dialog: MatDialog,
    private notification: NotificationService,
    /* 修正 No.53 (2026-04-24) */
    private confirmDialog: ConfirmDialogService,
    /* fix (2026-04-27): ルート遷移用 */
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.loadAppeals();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      this.loadAppeals();
    }
  }

  private loadAppeals(): void {
    if (!this.communityId) return;
    this.communityService.searchAppeals(this.communityId, '').subscribe(appeals => {
      this.allAppeals = appeals;
      this.applyFilter();
      this.cdr.markForCheck();
    });
  }

  applyFilter(): void {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) {
      this.filteredAppeals = [...this.allAppeals];
    } else {
      this.filteredAppeals = this.allAppeals.filter(a =>
        (a.title || '').toLowerCase().includes(term) ||
        (a.selfIntro || '').toLowerCase().includes(term) ||
        (a.skills || []).join(' ').toLowerCase().includes(term) ||
        (a.authorName || '').toLowerCase().includes(term) ||
        (a.wantToMeet || '').toLowerCase().includes(term) ||
        (a.authorCompany || '').toLowerCase().includes(term) ||
        (a.authorJobTitle || '').toLowerCase().includes(term)
      );
    }
    this.currentPage = 1;
    this.updatePagination();
  }

  private updatePagination(): void {
    this.totalPages = Math.max(1, Math.ceil(this.filteredAppeals.length / this.pageSize));
    if (this.currentPage > this.totalPages) {
      this.currentPage = this.totalPages;
    }
    const start = (this.currentPage - 1) * this.pageSize;
    this.pagedAppeals = this.filteredAppeals.slice(start, start + this.pageSize);
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePagination();
  }

  get pageNumbers(): number[] {
    const maxVisible = 5;
    let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
    let end = start + maxVisible - 1;
    if (end > this.totalPages) {
      end = this.totalPages;
      start = Math.max(1, end - maxVisible + 1);
    }
    const pages: number[] = [];
    for (let i = start; i <= end; i++) {
      pages.push(i);
    }
    return pages;
  }

  onSelectAppeal(appeal: Appeal): void {
    this.selectedAppeal = appeal;
  }

  onBackToList(): void {
    this.selectedAppeal = null;
  }

  /**
   * fix (2026-04-27): SP モーダルクリック不能問題対策。
   * MatDialog → ルート遷移 (/community/:id/sub/appeal/create) に変更。
   */
  onCreate(): void {
    this.router.navigate(['/community', this.communityId, 'sub', 'appeal', 'create']);
  }

  /** 自分が作成したアピールか (ユーザー指示 2026-04-21) */
  isMine(a: Appeal): boolean {
    return this.communityService.isCurrentUser(a.authorId);
  }

  onEdit(appeal: Appeal, ev?: Event): void {
    ev?.stopPropagation();
    const dialogRef = this.dialog.open(AppealCreateComponent, {
      width: '94vw',
      maxWidth: '560px',
      maxHeight: '90dvh',
      panelClass: 'community-create-dialog',
      data: { communityId: this.communityId, editing: appeal },
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.loadAppeals();
        this.notification.success('アピールを更新しました');
      }
    });
  }

  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async onDelete(appeal: Appeal, ev?: Event): Promise<void> {
    ev?.stopPropagation();
    const ok = await this.confirmDialog.confirm({
      title: 'アピールの削除',
      message: `「${appeal.title}」を削除してよろしいですか？`,
      confirmText: '削除',
      danger: true,
    });
    if (!ok) return;
    this.communityService.deleteAppeal(appeal.id).subscribe(() => {
      this.loadAppeals();
      this.notification.warn('アピールを削除しました');
    });
  }

  onInterested(appeal: Appeal): void {
    this.dialog.open(ChatRequestComponent, {
      width: '90vw',
      maxWidth: '420px',
      panelClass: 'community-create-dialog',
      data: {
        type: 'appeal',
        targetName: appeal.authorName,
        prefilledInfo: appeal.title,
        communityName: ''
      }
    });
  }

  onJoinRequest(): void {
    this.communityService.requestJoin(this.communityId).subscribe(() => {
      this.isMember = true;
      this.notification.success('参加申請が承認されました');
      this.cdr.markForCheck();
    });
  }
}
