import { Component, Output, EventEmitter, OnInit, OnDestroy, AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { Subject, Observable, Subscription } from 'rxjs';
import { debounceTime, distinctUntilChanged, switchMap, startWith } from 'rxjs/operators';
import { CommunityService } from '../../services/community.service';
import { Community, CommunityMember } from '../../models/community.model';
import { CommunityCardComponent } from '../community-card/community-card.component';

/* fix #17 (R-COM-02, 2026-04-27): コミュニティ一覧→詳細→戻る で scroll 位置がリセット
   される問題対策。一覧の scroll 位置を localStorage に保存し、再表示時に復元する。 */
const SCROLL_STORAGE_KEY = 'schecon.community-list.scrollTop.v1';

@Component({
  selector: 'app-community-list',
  standalone: true,
  imports: [CommonModule, MatIconModule, CommunityCardComponent],
  templateUrl: './community-list.component.html',
  styleUrls: ['./community-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CommunityListComponent implements OnInit, OnDestroy, AfterViewInit {
  @Output() selectCommunity = new EventEmitter<string>();
  @Output() createCommunity = new EventEmitter<void>();

  private searchSubject = new Subject<string>();
  allCommunities: Community[] = [];
  pagedCommunities: Community[] = [];
  memberPreviews = new Map<string, Observable<CommunityMember[]>>();
  membershipMap = new Map<string, boolean>();
  private subscription?: Subscription;

  currentPage = 1;
  pageSize = 40;
  totalPages = 1;

  constructor(
    private communityService: CommunityService,
    private cdr: ChangeDetectorRef,
  ) {}

  ngOnInit(): void {
    const communities$ = this.searchSubject.pipe(
      startWith(''),
      debounceTime(300),
      distinctUntilChanged(),
      switchMap(term => this.communityService.searchCommunities(term)),
    );

    this.subscription = communities$.subscribe(communities => {
      this.allCommunities = communities;
      this.currentPage = 1;
      this.totalPages = Math.ceil(communities.length / this.pageSize);
      // Track membership for all communities
      communities.forEach(c => {
        if (!this.membershipMap.has(c.id)) {
          this.communityService.isMember(c.id).subscribe(val => {
            this.membershipMap.set(c.id, val);
            this.cdr.markForCheck();
          });
        }
      });
      this.updatePage();
      this.cdr.markForCheck();
    });
  }

  ngAfterViewInit(): void {
    /* fix #17: ngAfterViewInit / 次フレームで scroll 位置を復元。
       一覧 DOM のレンダリング完了を待つために 2 段階 (microtask + rAF) を採用。 */
    queueMicrotask(() => this.restoreScroll());
    requestAnimationFrame(() => this.restoreScroll());
  }

  ngOnDestroy(): void {
    this.subscription?.unsubscribe();
  }

  /** fix #17: scroll container を取得。host (app-community-page) が overflow-y: auto。 */
  private getScrollEl(): HTMLElement | null {
    return (
      (document.querySelector('app-community-page') as HTMLElement | null) ||
      (document.scrollingElement as HTMLElement | null) ||
      document.documentElement
    );
  }

  /** fix #17: localStorage から scrollTop を取得して復元 */
  private restoreScroll(): void {
    try {
      const raw = localStorage.getItem(SCROLL_STORAGE_KEY);
      if (raw == null) return;
      const top = parseInt(raw, 10);
      if (Number.isNaN(top) || top < 0) return;
      const el = this.getScrollEl();
      if (el) el.scrollTop = top;
    } catch {
      /* localStorage 不可環境では無視 */
    }
  }

  /** fix #17: 現在の scrollTop を localStorage に保存 */
  private saveScroll(): void {
    try {
      const el = this.getScrollEl();
      const top = el ? el.scrollTop : window.scrollY;
      localStorage.setItem(SCROLL_STORAGE_KEY, String(Math.max(0, Math.floor(top))));
    } catch {
      /* localStorage 不可環境では無視 */
    }
  }

  private updatePage(): void {
    const start = (this.currentPage - 1) * this.pageSize;
    const end = start + this.pageSize;
    this.pagedCommunities = this.allCommunities.slice(start, end);
    this.pagedCommunities.forEach(c => {
      if (!this.memberPreviews.has(c.id)) {
        this.memberPreviews.set(c.id, this.communityService.getRandomMembers(c.id, 3));
      }
    });
  }

  onSearch(event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    this.searchSubject.next(value);
  }

  getMemberPreviews(communityId: string): Observable<CommunityMember[]> {
    if (!this.memberPreviews.has(communityId)) {
      this.memberPreviews.set(communityId, this.communityService.getRandomMembers(communityId, 3));
    }
    return this.memberPreviews.get(communityId)!;
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePage();
    this.cdr.markForCheck();
    // Scroll to top
    const el = document.querySelector('app-community-page') as HTMLElement | null;
    if (el) el.scrollTop = 0;
    /* fix #17: ページ切替時は保存済の scroll 位置をクリア (古いページの位置に戻ると不自然) */
    try {
      localStorage.removeItem(SCROLL_STORAGE_KEY);
    } catch {
      /* ignore */
    }
  }

  get pageNumbers(): number[] {
    const pages: number[] = [];
    const maxVisible = 5;
    let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
    let end = Math.min(this.totalPages, start + maxVisible - 1);
    if (end - start < maxVisible - 1) {
      start = Math.max(1, end - maxVisible + 1);
    }
    for (let i = start; i <= end; i++) {
      pages.push(i);
    }
    return pages;
  }

  onSelectCommunity(id: string): void {
    /* fix #17: 詳細遷移直前に scroll 位置を保存し、戻った時に復元できるようにする */
    this.saveScroll();
    this.selectCommunity.emit(id);
  }

  onCreateCommunity(): void {
    this.createCommunity.emit();
  }
}
