import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { CommunityMember } from '../../models/community.model';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { BlurOverlayComponent } from '../blur-overlay/blur-overlay.component';
import { MemberProfileComponent } from '../member-profile/member-profile.component';
import { ChatRequestComponent } from '../chat-request/chat-request.component';

@Component({
  selector: 'app-member-list',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, MatDialogModule, AvatarComponent, BlurOverlayComponent, MemberProfileComponent],
  templateUrl: './member-list.component.html',
  styleUrls: ['./member-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MemberListComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Input() isMember = false;
  @Output() chatRequest = new EventEmitter<CommunityMember>();

  allMembers: CommunityMember[] = [];
  filteredMembers: CommunityMember[] = [];
  pagedMembers: CommunityMember[] = [];

  searchTerm = '';
  currentPage = 1;
  pageSize = 10;
  totalPages = 1;

  selectedMember: CommunityMember | null = null;

  constructor(
    private communityService: CommunityService,
    private cdr: ChangeDetectorRef,
    private dialog: MatDialog,
    private notification: NotificationService,
  ) {}

  ngOnInit(): void {
    this.loadMembers();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      this.loadMembers();
    }
  }

  private loadMembers(): void {
    if (!this.communityId) return;
    this.communityService.searchMembers(this.communityId, '').subscribe(members => {
      this.allMembers = members;
      this.applyFilter();
      this.cdr.markForCheck();
    });
  }

  applyFilter(): void {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) {
      this.filteredMembers = [...this.allMembers];
    } else {
      this.filteredMembers = this.allMembers.filter(m =>
        m.name.toLowerCase().includes(term) ||
        m.company.toLowerCase().includes(term) ||
        m.jobTitle.toLowerCase().includes(term)
      );
    }
    this.currentPage = 1;
    this.updatePagination();
  }

  private updatePagination(): void {
    this.totalPages = Math.max(1, Math.ceil(this.filteredMembers.length / this.pageSize));
    if (this.currentPage > this.totalPages) this.currentPage = this.totalPages;
    const start = (this.currentPage - 1) * this.pageSize;
    this.pagedMembers = this.filteredMembers.slice(start, start + this.pageSize);
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePagination();
  }

  get pageNumbers(): number[] {
    const maxVisible = 5;
    let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
    let end = start + maxVisible - 1;
    if (end > this.totalPages) {
      end = this.totalPages;
      start = Math.max(1, end - maxVisible + 1);
    }
    const pages: number[] = [];
    for (let i = start; i <= end; i++) pages.push(i);
    return pages;
  }

  onMemberClick(member: CommunityMember): void {
    this.selectedMember = member;
  }

  onCloseProfile(): void {
    this.selectedMember = null;
  }

  onChat(member: CommunityMember): void {
    this.dialog.open(ChatRequestComponent, {
      width: '90vw',
      maxWidth: '420px',
      panelClass: 'community-create-dialog',
      data: {
        type: 'member',
        targetName: member.name,
        communityName: ''
      }
    });
  }

  onJoinRequest(): void {
    this.communityService.requestJoin(this.communityId).subscribe(() => {
      this.isMember = true;
      this.notification.success('参加申請が承認されました');
      this.cdr.markForCheck();
    });
  }
}
