import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { Community, CommunityMember, CATEGORY_ICONS } from '../../models/community.model';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { TruncatePipe } from '../../../../shared/pipes/truncate.pipe';

@Component({
  selector: 'app-community-card',
  standalone: true,
  imports: [CommonModule, MatIconModule, AvatarComponent, TruncatePipe],
  templateUrl: './community-card.component.html',
  styleUrls: ['./community-card.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CommunityCardComponent {
  @Input() community!: Community;
  categoryIcons = CATEGORY_ICONS;
  @Input() memberAvatars: CommunityMember[] = [];
  @Input() isMember = false;
  @Output() select = new EventEmitter<string>();

  onCardClick(): void {
    this.select.emit(this.community.id);
  }
}
