import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { Observable, of } from 'rxjs';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { NewsItem, NewsComment } from '../../models/community.model';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';

@Component({
  selector: 'app-news-detail',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, AvatarComponent, RelativeTimePipe],
  templateUrl: './news-detail.component.html',
  styleUrl: './news-detail.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class NewsDetailComponent implements OnInit, OnChanges {
  @Input() newsId = '';
  @Input() isMember = false;
  @Output() back = new EventEmitter<void>();

  news$: Observable<NewsItem | undefined> = of(undefined);
  comments$: Observable<NewsComment[]> = of([]);
  newComment = '';

  constructor(
    private communityService: CommunityService,
    private notification: NotificationService,
    private cdr: ChangeDetectorRef,
  ) {}

  /** 元記事クリック処理 (ユーザー指示 修正 #11): デモ用ニュースのため
   *  リンク先は実在しないことが多いので、クリックをインターセプトして
   *  案内のトーストを表示 + 元ソースサイトの TOP へフォールバック遷移。 */
  onSourceClick(event: MouseEvent, news: NewsItem): void {
    event.preventDefault();
    event.stopPropagation();
    try {
      const url = new URL(news.sourceUrl);
      const homepage = `${url.protocol}//${url.host}/`;
      this.notification.info(`デモ用ニュースのため元記事は存在しません。${news.source} のサイトTOPを新規タブで開きます。`);
      window.open(homepage, '_blank', 'noopener,noreferrer');
    } catch {
      this.notification.warn('元記事 URL が開けませんでした');
    }
  }

  ngOnInit(): void {
    this.loadData();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['newsId'] && !changes['newsId'].firstChange) {
      this.loadData();
    }
  }

  private loadData(): void {
    if (this.newsId) {
      this.news$ = this.communityService.getNewsItem(this.newsId);
      this.comments$ = this.communityService.getNewsComments(this.newsId);
    }
  }

  onBack(): void {
    this.back.emit();
  }

  submitComment(): void {
    if (!this.newComment.trim() || !this.isMember) return;
    this.communityService.addNewsComment(this.newsId, this.newComment.trim()).subscribe(() => {
      this.newComment = '';
      this.comments$ = this.communityService.getNewsComments(this.newsId);
      this.cdr.markForCheck();
    });
  }

  likeComment(commentId: string): void {
    this.communityService.likeComment(commentId);
    this.comments$ = this.communityService.getNewsComments(this.newsId);
    this.cdr.markForCheck();
  }
}
