import { Component, Input, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ThreadPost } from '../../models/community.model';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { BlurOverlayComponent } from '../blur-overlay/blur-overlay.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { ThreadCreateComponent } from '../thread-create/thread-create.component';
import { ThreadDetailComponent } from '../thread-detail/thread-detail.component';
/* 修正 No.53 (2026-04-24): ネイティブ confirm をサイト配色のモーダルへ置換 */
import { ConfirmDialogService } from '../../../../shared/services/confirm-dialog.service';

@Component({
  selector: 'app-thread-list',
  standalone: true,
  imports: [CommonModule, MatIconModule, MatDialogModule, FormsModule, BlurOverlayComponent, AvatarComponent, ThreadDetailComponent],
  templateUrl: './thread-list.component.html',
  styleUrls: ['./thread-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ThreadListComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Input() isMember = false;

  allThreads: ThreadPost[] = [];
  filteredThreads: ThreadPost[] = [];
  pagedThreads: ThreadPost[] = [];
  searchTerm = '';

  currentPage = 1;
  pageSize = 10;
  totalPages = 1;

  selectedThread: ThreadPost | null = null;

  constructor(
    private communityService: CommunityService,
    private dialog: MatDialog,
    private notification: NotificationService,
    private cdr: ChangeDetectorRef,
    /* 修正 No.53 (2026-04-24) */
    private confirmDialog: ConfirmDialogService,
    /* fix (2026-04-27): ルート遷移用 */
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.loadThreads();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      this.loadThreads();
    }
  }

  private loadThreads(): void {
    if (this.communityId) {
      this.communityService.getThreads(this.communityId).subscribe(threads => {
        this.allThreads = threads;
        this.applyFilter();
        this.cdr.markForCheck();
      });
    }
  }

  applyFilter(): void {
    const term = this.searchTerm.toLowerCase().trim();
    if (!term) {
      this.filteredThreads = [...this.allThreads];
    } else {
      this.filteredThreads = this.allThreads.filter(t =>
        t.title.toLowerCase().includes(term) ||
        t.content.toLowerCase().includes(term) ||
        t.authorName.toLowerCase().includes(term) ||
        (t.authorCompany || '').toLowerCase().includes(term) ||
        (t.authorJobTitle || '').toLowerCase().includes(term) ||
        (t.tags || []).join(' ').toLowerCase().includes(term)
      );
    }
    this.currentPage = 1;
    this.updatePagination();
  }

  private updatePagination(): void {
    this.totalPages = Math.max(1, Math.ceil(this.filteredThreads.length / this.pageSize));
    if (this.currentPage > this.totalPages) this.currentPage = this.totalPages;
    const start = (this.currentPage - 1) * this.pageSize;
    this.pagedThreads = this.filteredThreads.slice(start, start + this.pageSize);
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePagination();
  }

  get pageNumbers(): number[] {
    const maxVisible = 5;
    let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
    let end = start + maxVisible - 1;
    if (end > this.totalPages) {
      end = this.totalPages;
      start = Math.max(1, end - maxVisible + 1);
    }
    const pages: number[] = [];
    for (let i = start; i <= end; i++) pages.push(i);
    return pages;
  }

  onSelectThread(thread: ThreadPost): void {
    this.selectedThread = thread;
  }

  onBackToList(): void {
    this.selectedThread = null;
  }

  /**
   * fix (2026-04-27): SP モーダルクリック不能問題対策。
   * MatDialog → ルート遷移 (/community/:id/sub/thread/create) に変更。
   */
  onCreate(): void {
    this.router.navigate(['/community', this.communityId, 'sub', 'thread', 'create']);
  }

  /** 自分のスレッドか (ユーザー指示 2026-04-21) */
  isMine(t: ThreadPost): boolean {
    return this.communityService.isCurrentUser(t.authorId);
  }

  /** 編集 */
  onEditThread(thread: ThreadPost, ev?: Event): void {
    ev?.stopPropagation();
    const dialogRef = this.dialog.open(ThreadCreateComponent, {
      width: '94vw',
      maxWidth: '560px',
      maxHeight: '90dvh',
      panelClass: 'community-create-dialog',
      data: { communityId: this.communityId, editing: thread },
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result && result.editing) {
        this.communityService
          .updateThread(thread.id, { title: result.title, content: result.content })
          .subscribe(() => {
            this.loadThreads();
            this.notification.success('スレッドを更新しました');
          });
      }
    });
  }

  /** 削除 */
  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async onDeleteThread(thread: ThreadPost, ev?: Event): Promise<void> {
    ev?.stopPropagation();
    const ok = await this.confirmDialog.confirm({
      title: 'スレッドの削除',
      message: `「${thread.title}」を削除してよろしいですか？`,
      confirmText: '削除',
      danger: true,
    });
    if (!ok) return;
    this.communityService.deleteThread(thread.id).subscribe(() => {
      this.loadThreads();
      this.notification.warn('スレッドを削除しました');
    });
  }

  /** スレッドへのリアクション切替 */
  onToggleReaction(thread: ThreadPost, kind: 'like' | 'clap' | 'heart' | 'bulb' | 'laugh' | 'fire', ev?: Event): void {
    ev?.stopPropagation();
    this.communityService.toggleThreadReaction(thread.id, kind);
    this.loadThreads();
  }

  /** テンプレ用ヘルパ: リアクション件数 */
  reactionCount(thread: ThreadPost, kind: string): number {
    return (thread.reactions || []).find(r => r.kind === kind)?.count || 0;
  }
  /** テンプレ用ヘルパ: 自分が押しているか */
  reactionByMe(thread: ThreadPost, kind: string): boolean {
    return !!(thread.reactions || []).find(r => r.kind === kind)?.byMe;
  }

  readonly reactionKinds: ('like'|'clap'|'heart'|'bulb'|'laugh'|'fire')[] = ['like','clap','heart','bulb','laugh','fire'];

  reactionEmoji(kind: string): string {
    switch (kind) {
      case 'like': return '👍';
      case 'clap': return '👏';
      case 'heart': return '❤️';
      case 'bulb': return '💡';
      case 'laugh': return '😂';
      case 'fire': return '🔥';
      default: return '';
    }
  }

  /* fix D8 (2026-04-28): リアクションボタンを 1 個 + バリエーションポップアップ化
     - reactionPickerOpenId: 現在ポップアップを開いているスレッド id (null = 全て閉じる)
     - toggleReactionPicker: + アイコンクリックで開閉
     - selectReaction: ポップアップから絵文字選択 → toggleThreadReaction → ポップアップ閉じる
     - userReactions: 自分が押したリアクションのみ抽出 (pill 表示用) */
  reactionPickerOpenId: string | null = null;

  toggleReactionPicker(threadId: string, ev: Event): void {
    ev.stopPropagation();
    this.reactionPickerOpenId = this.reactionPickerOpenId === threadId ? null : threadId;
  }

  selectReaction(thread: ThreadPost, kind: 'like'|'clap'|'heart'|'bulb'|'laugh'|'fire', ev: Event): void {
    ev.stopPropagation();
    this.onToggleReaction(thread, kind, ev);
    this.reactionPickerOpenId = null;
  }

  /** 自分が押したリアクションのみ (pill 表示用) */
  userReactions(thread: ThreadPost): { kind: string; count: number }[] {
    return (thread.reactions || []).filter(r => (r.count || 0) > 0);
  }

  /** ポップアップ外クリックで閉じる用ヘルパ */
  closeReactionPicker(): void {
    this.reactionPickerOpenId = null;
  }

  onJoinRequest(): void {
    this.communityService.requestJoin(this.communityId).subscribe(() => {
      this.isMember = true;
      this.notification.success('参加申請が承認されました');
      this.cdr.markForCheck();
    });
  }

  formatDate(date: Date): string {
    const d = new Date(date);
    return `${d.getMonth() + 1}/${d.getDate()}`;
  }
}
