import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { Recruitment } from '../../models/community.model';
import { BlurOverlayComponent } from '../blur-overlay/blur-overlay.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { TruncatePipe } from '../../../../shared/pipes/truncate.pipe';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';
import { RecruitmentDetailComponent } from '../recruitment-detail/recruitment-detail.component';
import { RecruitmentCreateComponent } from '../recruitment-create/recruitment-create.component';
import { ChatRequestComponent } from '../chat-request/chat-request.component';
/* 修正 No.53 (2026-04-24): ネイティブ confirm をサイト配色のモーダルへ置換 */
import { ConfirmDialogService } from '../../../../shared/services/confirm-dialog.service';

@Component({
  selector: 'app-recruitment-list',
  standalone: true,
  imports: [CommonModule, FormsModule, MatIconModule, MatDialogModule, BlurOverlayComponent, AvatarComponent, TruncatePipe, RelativeTimePipe, RecruitmentDetailComponent],
  templateUrl: './recruitment-list.component.html',
  styleUrls: ['./recruitment-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RecruitmentListComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Input() isMember = false;
  @Output() selectRecruitment = new EventEmitter<Recruitment>();
  @Output() createRecruitment = new EventEmitter<void>();

  allRecruitments: Recruitment[] = [];
  filteredRecruitments: Recruitment[] = [];
  pagedRecruitments: Recruitment[] = [];

  searchTerm = '';
  currentPage = 1;
  pageSize = 10;
  totalPages = 1;

  selectedRecruitment: Recruitment | null = null;

  constructor(
    private communityService: CommunityService,
    private cdr: ChangeDetectorRef,
    private dialog: MatDialog,
    private notification: NotificationService,
    /* 修正 No.53 (2026-04-24) */
    private confirmDialog: ConfirmDialogService,
    /* fix (2026-04-27): ルート遷移用 */
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.loadRecruitments();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      this.loadRecruitments();
    }
  }

  private loadRecruitments(): void {
    if (!this.communityId) return;
    this.communityService.searchRecruitments(this.communityId, '').subscribe(data => {
      this.allRecruitments = data;
      this.applyFilter();
      this.cdr.markForCheck();
    });
  }

  applyFilter(): void {
    const term = this.searchTerm.trim().toLowerCase();
    if (!term) {
      this.filteredRecruitments = [...this.allRecruitments];
    } else {
      this.filteredRecruitments = this.allRecruitments.filter(r =>
        (r.title?.toLowerCase().includes(term)) ||
        (r.problem?.toLowerCase().includes(term)) ||
        (r.details?.toLowerCase().includes(term)) ||
        (r.authorName?.toLowerCase().includes(term))
      );
    }
    this.totalPages = Math.max(1, Math.ceil(this.filteredRecruitments.length / this.pageSize));
    if (this.currentPage > this.totalPages) {
      this.currentPage = 1;
    }
    this.updatePage();
  }

  private updatePage(): void {
    const start = (this.currentPage - 1) * this.pageSize;
    this.pagedRecruitments = this.filteredRecruitments.slice(start, start + this.pageSize);
  }

  goToPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    this.updatePage();
  }

  get pageNumbers(): number[] {
    const pages: number[] = [];
    for (let i = 1; i <= this.totalPages; i++) {
      pages.push(i);
    }
    return pages;
  }

  onSelect(recruitment: Recruitment): void {
    this.selectedRecruitment = recruitment;
  }

  onBackToList(): void {
    this.selectedRecruitment = null;
  }

  /**
   * fix (2026-04-27): SP モーダルクリック不能問題対策。
   * MatDialog → ルート遷移 (/community/:id/sub/recruitment/create) に変更。
   * 戻る時は location.back で list に復帰、loadRecruitments は ngOnInit/onChanges で再走。
   */
  onCreate(): void {
    this.router.navigate(['/community', this.communityId, 'sub', 'recruitment', 'create']);
  }

  /** 自分が作成した投稿か (ユーザー指示 2026-04-21) */
  isMine(r: Recruitment): boolean {
    return this.communityService.isCurrentUser(r.authorId);
  }

  /** 編集ダイアログを開く (ユーザー指示 2026-04-21) */
  onEdit(rec: Recruitment, ev?: Event): void {
    ev?.stopPropagation();
    const dialogRef = this.dialog.open(RecruitmentCreateComponent, {
      width: '94vw',
      maxWidth: '560px',
      maxHeight: '90dvh',
      panelClass: 'community-create-dialog',
      data: { communityId: this.communityId, editing: rec },
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.loadRecruitments();
        this.notification.success('募集を更新しました');
      }
    });
  }

  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async onDelete(rec: Recruitment, ev?: Event): Promise<void> {
    ev?.stopPropagation();
    const ok = await this.confirmDialog.confirm({
      title: '募集の削除',
      message: `「${rec.title}」を削除してよろしいですか？`,
      confirmText: '削除',
      danger: true,
    });
    if (!ok) return;
    this.communityService.deleteRecruitment(rec.id).subscribe(() => {
      this.loadRecruitments();
      this.notification.warn('募集を削除しました');
    });
  }

  onApply(recruitment: Recruitment): void {
    this.dialog.open(ChatRequestComponent, {
      width: '90vw',
      maxWidth: '420px',
      panelClass: 'community-create-dialog',
      data: {
        type: 'recruitment',
        targetName: recruitment.authorName,
        prefilledInfo: recruitment.title,
        communityName: ''
      }
    });
  }

  onJoinRequest(): void {
    this.communityService.requestJoin(this.communityId).subscribe(() => {
      this.isMember = true;
      this.notification.success('参加申請が承認されました');
      this.cdr.markForCheck();
    });
  }
}
