import { Component, ChangeDetectionStrategy, OnDestroy, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { Subject, takeUntil } from 'rxjs';
import { CommunityListComponent } from '../../components/community-list/community-list.component';
import { CommunityDetailComponent } from '../../components/community-detail/community-detail.component';
/* fix (2026-04-27): MatDialog + CommunityCreateComponent インポート撤去
   (新規作成は /community/create ページに分離) */


@Component({
  selector: 'app-community-page',
  standalone: true,
  imports: [CommonModule, CommunityListComponent, CommunityDetailComponent],
  templateUrl: './community-page.component.html',
  styleUrl: './community-page.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CommunityPageComponent implements OnInit, OnDestroy {
  communityId: string | null = null;
  private destroy$ = new Subject<void>();

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private titleService: Title,
  ) {
    this.route.params.pipe(takeUntil(this.destroy$)).subscribe(params => {
      this.communityId = params['id'] || null;
    });
  }

  ngOnInit(): void {
    this.titleService.setTitle('コミュニティ | 日程調整ツール"スケコン"');
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  onSelectCommunity(id: string): void {
    this.router.navigate(['/community', id]);
  }

  onBackToList(): void {
    this.router.navigate(['/community']);
  }

  /**
   * fix (2026-04-27): SP モーダルクリック不能問題対策。
   * MatDialog による community-create モーダル → /community/create ページ遷移に変更。
   * PC でも一貫した動作 (URL 化、ブラウザ戻る対応、z-index 戦争回避)。
   */
  onCreateCommunity(): void {
    this.router.navigate(['/community/create']);
  }
}
