import { Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { NotificationService } from '../../../../shared/services/notification.service';
import { Observable, of } from 'rxjs';
import { CommunityService } from '../../services/community.service';
import { Community, CommunityTab, CATEGORY_ICONS } from '../../models/community.model';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { MemberListComponent } from '../member-list/member-list.component';
import { RecruitmentListComponent } from '../recruitment-list/recruitment-list.component';
import { AppealListComponent } from '../appeal-list/appeal-list.component';
import { ThreadListComponent } from '../thread-list/thread-list.component';
import { NewsListComponent } from '../news-list/news-list.component';
import { EventListComponent } from '../event-list/event-list.component';

@Component({
  selector: 'app-community-detail',
  standalone: true,
  imports: [
    CommonModule,
    MatIconModule,
    AvatarComponent,
    MemberListComponent,
    RecruitmentListComponent,
    AppealListComponent,
    ThreadListComponent,
    NewsListComponent,
    EventListComponent,
  ],
  templateUrl: './community-detail.component.html',
  styleUrls: ['./community-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CommunityDetailComponent implements OnInit, OnChanges {
  @Input() communityId = '';
  @Output() back = new EventEmitter<void>();

  community$: Observable<Community | undefined> = of(undefined);
  isMember$: Observable<boolean> = of(false);
  activeTab: CommunityTab = 'members';
  categoryIcons = CATEGORY_ICONS;

  /* ユーザー指示 (2026-04-27): メンバーを一番左に移動。
     旧: 募集/アピール/イベント/スレッド/ニュース/メンバー
     新: メンバー/募集/アピール/イベント/スレッド/ニュース */
  tabs: { key: CommunityTab; label: string }[] = [
    { key: 'members', label: 'メンバー' },
    { key: 'recruitment', label: '募集' },
    { key: 'appeals', label: 'アピール' },
    { key: 'events', label: 'イベント' },
    { key: 'threads', label: 'スレッド' },
    { key: 'news', label: 'ニュース' },
  ];

  constructor(
    private communityService: CommunityService,
    private notification: NotificationService,
  ) {}

  /* fix #20 (R-COM-05改, 2026-04-27): community 詳細のアクティブタブを
     localStorage に保存し、再表示時に復元する。コミュニティ毎に独立。 */
  private static readonly TAB_STORAGE_PREFIX = 'schecon.community-detail.tab.v1.';
  private static readonly VALID_TABS: readonly CommunityTab[] = [
    'members', 'recruitment', 'appeals', 'events', 'threads', 'news',
  ];

  ngOnInit(): void {
    this.activeTab = this.loadStoredTab(this.communityId);
    this.loadData();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['communityId'] && !changes['communityId'].firstChange) {
      /* fix #20: コミュニティが切り替わった場合は新 ID 用の保存値を読む */
      this.activeTab = this.loadStoredTab(this.communityId);
      this.loadData();
    }
  }

  /** fix #20: 指定 community の保存タブを取得。なければデフォルト 'members'。 */
  private loadStoredTab(communityId: string): CommunityTab {
    if (!communityId) return 'members';
    try {
      const raw = localStorage.getItem(CommunityDetailComponent.TAB_STORAGE_PREFIX + communityId);
      if (raw && (CommunityDetailComponent.VALID_TABS as readonly string[]).includes(raw)) {
        return raw as CommunityTab;
      }
    } catch {
      /* localStorage 不可環境では無視 */
    }
    return 'members';
  }

  /** fix #20: 現在のアクティブタブを localStorage に保存 */
  private persistTab(tab: CommunityTab): void {
    if (!this.communityId) return;
    try {
      localStorage.setItem(
        CommunityDetailComponent.TAB_STORAGE_PREFIX + this.communityId,
        tab,
      );
    } catch {
      /* localStorage 不可環境では無視 */
    }
  }

  private loadData(): void {
    if (this.communityId) {
      this.community$ = this.communityService.getCommunity(this.communityId);
      this.isMember$ = this.communityService.isMember(this.communityId);
    }
  }

  setTab(tab: CommunityTab): void {
    this.activeTab = tab;
    /* fix #20: タブ切替を localStorage に永続化 */
    this.persistTab(tab);
  }

  onJoin(): void {
    this.communityService.requestJoin(this.communityId).subscribe(() => {
      this.isMember$ = this.communityService.isMember(this.communityId);
      this.notification.success('参加申請が承認されました');
    });
  }

  onBack(): void {
    this.back.emit();
  }
}
