import { Component, Input, Output, EventEmitter, OnInit, OnDestroy, HostListener, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { FormsModule } from '@angular/forms';
import { Observable, of } from 'rxjs';
import { ThreadPost, ThreadComment, ReactionKind } from '../../models/community.model';
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';
import { FormDraftService } from '../../../../shared/services/form-draft.service';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';
/* 修正 No.53 (2026-04-24): ネイティブ confirm をサイト配色のモーダルへ置換 */
import { ConfirmDialogService } from '../../../../shared/services/confirm-dialog.service';

interface ReplyDraft { text: string; }

@Component({
  selector: 'app-thread-detail',
  standalone: true,
  imports: [CommonModule, MatIconModule, FormsModule, AvatarComponent, RelativeTimePipe],
  templateUrl: './thread-detail.component.html',
  styleUrls: ['./thread-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ThreadDetailComponent implements OnInit, OnDestroy {
  @Input() thread!: ThreadPost;
  @Input() isMember = false;
  @Output() back = new EventEmitter<void>();

  replyText = '';
  comments$: Observable<ThreadComment[]> = of([]);

  /** 編集中のコメント ID (ユーザー指示 2026-04-21) */
  editingCommentId: string | null = null;
  editingCommentText = '';

  /** 利用可能なリアクション種類 */
  readonly REACTION_KINDS: ReactionKind[] = ['like', 'clap', 'heart', 'bulb', 'laugh', 'fire'];

  constructor(
    private communityService: CommunityService,
    private notification: NotificationService,
    private draftSvc: FormDraftService,
    private cdr: ChangeDetectorRef,
    /* 修正 No.53 (2026-04-24) */
    private confirmDialog: ConfirmDialogService,
  ) {}

  /** スレッド別の下書きキー (ユーザー指示 2026-04-21) */
  private get replyDraftKey(): string { return 'thread-reply:' + this.thread?.id; }

  ngOnInit(): void {
    this.loadComments();
    // 下書きを復元 (ユーザー指示 2026-04-21): 投稿中に離脱しても戻ってきたら続きから
    const draft = this.draftSvc.load<ReplyDraft>(this.replyDraftKey);
    if (draft?.text) this.replyText = draft.text;
  }

  @HostListener('window:beforeunload')
  onBeforeUnload(): void {
    if (this.replyText) this.draftSvc.flush(this.replyDraftKey, { text: this.replyText });
  }

  ngOnDestroy(): void {
    if (this.replyText) this.draftSvc.flush(this.replyDraftKey, { text: this.replyText });
  }

  onReplyChange(): void {
    this.draftSvc.save(this.replyDraftKey, { text: this.replyText });
  }

  private loadComments(): void {
    if (this.thread?.id) {
      this.comments$ = this.communityService.getThreadComments(this.thread.id);
    }
  }

  onBack(): void {
    this.back.emit();
  }

  onSubmitReply(): void {
    if (!this.replyText.trim()) return;
    this.communityService.addThreadComment(this.thread.id, this.replyText.trim()).subscribe(() => {
      this.replyText = '';
      this.draftSvc.clear(this.replyDraftKey);
      this.comments$ = this.communityService.getThreadComments(this.thread.id);
      this.thread.replies++;
      this.cdr.markForCheck();
    });
  }

  /** 修正 No.18 (2026-04-24): Vote / Like の無限カウントアップを防ぐトグル化 */
  private _voted = false;
  private _liked = false;
  private _likedComments = new Set<string>();

  onVote(): void {
    if (this._voted) {
      this.thread.votes = Math.max(0, (this.thread.votes || 0) - 1);
      this._voted = false;
    } else {
      this.thread.votes = (this.thread.votes || 0) + 1;
      this._voted = true;
    }
  }

  onLike(): void {
    if (this._liked) {
      this.thread.likes = Math.max(0, this.thread.likes - 1);
      this._liked = false;
    } else {
      this.thread.likes++;
      this._liked = true;
    }
  }

  isVoted(): boolean { return this._voted; }
  isLiked(): boolean { return this._liked; }

  onLikeComment(commentId: string): void {
    /* 修正 No.18 (2026-04-24): コメントいいねもトグル制にする */
    if (this._likedComments.has(commentId)) {
      this._likedComments.delete(commentId);
      this.communityService.unlikeThreadComment(commentId);
    } else {
      this._likedComments.add(commentId);
      this.communityService.likeThreadComment(commentId);
    }
    this.comments$ = this.communityService.getThreadComments(this.thread.id);
    this.cdr.markForCheck();
  }

  isCommentLiked(commentId: string): boolean {
    return this._likedComments.has(commentId);
  }

  /** コメント作者が自分か (ユーザー指示 2026-04-21) */
  isMyComment(c: ThreadComment): boolean {
    return this.communityService.isCurrentUser(c.authorId);
  }
  isMyThread(): boolean {
    return this.communityService.isCurrentUser(this.thread.authorId);
  }

  /** コメント編集開始 */
  startEditComment(c: ThreadComment): void {
    this.editingCommentId = c.id;
    this.editingCommentText = c.content;
  }
  cancelEditComment(): void {
    this.editingCommentId = null;
    this.editingCommentText = '';
  }
  saveEditComment(): void {
    if (!this.editingCommentId || !this.editingCommentText.trim()) return;
    this.communityService
      .updateThreadComment(this.editingCommentId, this.editingCommentText.trim())
      .subscribe(() => {
        this.editingCommentId = null;
        this.editingCommentText = '';
        this.comments$ = this.communityService.getThreadComments(this.thread.id);
        this.notification.success('コメントを更新しました');
        this.cdr.markForCheck();
      });
  }

  /* 修正 No.53 (2026-04-24): 独自 confirm モーダル化 */
  async deleteComment(c: ThreadComment): Promise<void> {
    const ok = await this.confirmDialog.confirm({
      title: 'コメントの削除',
      message: 'このコメントを削除してよろしいですか？',
      confirmText: '削除',
      danger: true,
    });
    if (!ok) return;
    this.communityService.deleteThreadComment(c.id).subscribe(() => {
      this.comments$ = this.communityService.getThreadComments(this.thread.id);
      this.thread.replies = Math.max(0, this.thread.replies - 1);
      this.notification.warn('コメントを削除しました');
      this.cdr.markForCheck();
    });
  }

  /** スレッド本体のリアクション */
  toggleThreadReaction(kind: ReactionKind): void {
    this.communityService.toggleThreadReaction(this.thread.id, kind);
    // 直接 thread オブジェクトを書き換え (UI 即時反映)
    const existing = (this.thread.reactions || []).find(r => r.kind === kind);
    if (existing) {
      if (existing.byMe) {
        existing.count = Math.max(0, existing.count - 1);
        existing.byMe = false;
        if (existing.count === 0) {
          this.thread.reactions = (this.thread.reactions || []).filter(r => r.kind !== kind);
        }
      } else {
        existing.count++;
        existing.byMe = true;
      }
    } else {
      this.thread.reactions = [...(this.thread.reactions || []), { kind, count: 1, byMe: true }];
    }
    this.cdr.markForCheck();
  }

  /** コメントのリアクション */
  toggleCommentReaction(c: ThreadComment, kind: ReactionKind): void {
    this.communityService.toggleThreadCommentReaction(c.id, kind);
    this.comments$ = this.communityService.getThreadComments(this.thread.id);
    this.cdr.markForCheck();
  }

  reactionEmoji(kind: ReactionKind): string {
    switch (kind) {
      case 'like': return '👍';
      case 'clap': return '👏';
      case 'heart': return '❤️';
      case 'bulb': return '💡';
      case 'laugh': return '😂';
      case 'fire': return '🔥';
    }
  }

  reactionCount(arr: { kind: ReactionKind; count: number; byMe?: boolean }[] | undefined, kind: ReactionKind): number {
    return (arr || []).find(r => r.kind === kind)?.count || 0;
  }

  reactionByMe(arr: { kind: ReactionKind; count: number; byMe?: boolean }[] | undefined, kind: ReactionKind): boolean {
    return !!(arr || []).find(r => r.kind === kind)?.byMe;
  }

  /* fix D8 (2026-04-28): スレッド本体 + コメント用のリアクションポップアップ
     - threadPickerOpen: スレッド本体のポップアップ開閉
     - commentPickerOpenId: コメント (id) のポップアップ開閉 */
  threadPickerOpen = false;
  commentPickerOpenId: string | null = null;

  toggleThreadPicker(ev: Event): void {
    ev.stopPropagation();
    this.threadPickerOpen = !this.threadPickerOpen;
    this.commentPickerOpenId = null;
  }
  toggleCommentPicker(commentId: string, ev: Event): void {
    ev.stopPropagation();
    this.commentPickerOpenId = this.commentPickerOpenId === commentId ? null : commentId;
    this.threadPickerOpen = false;
  }
  selectThreadReaction(kind: ReactionKind, ev: Event): void {
    ev.stopPropagation();
    this.toggleThreadReaction(kind);
    this.threadPickerOpen = false;
  }
  selectCommentReaction(c: ThreadComment, kind: ReactionKind, ev: Event): void {
    ev.stopPropagation();
    this.toggleCommentReaction(c, kind);
    this.commentPickerOpenId = null;
  }
}
