import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { CommunityEvent, EventRSVP, EventParticipant } from '../../models/community.model';
import { CommunityService } from '../../services/community.service';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';

@Component({
  selector: 'app-event-detail',
  standalone: true,
  imports: [CommonModule, MatIconModule, AvatarComponent, RelativeTimePipe],
  templateUrl: './event-detail.component.html',
  styleUrls: ['./event-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventDetailComponent {
  @Input() event!: CommunityEvent;
  @Input() isMember = false;
  @Output() back = new EventEmitter<void>();

  /** 参加者一覧モーダル (ユーザー指示 2026-04-21) */
  showParticipantsModal = false;
  /** 一覧フィルタ: all / going / maybe */
  participantsFilter: 'all' | 'going' | 'maybe' = 'all';

  constructor(
    private communityService: CommunityService,
    private cdr: ChangeDetectorRef,
  ) {}

  get isParticipant(): boolean {
    return this.event.participants.some(p => p.id === 'current-user');
  }

  /** 現在ユーザーの RSVP ステータス */
  get myRsvp(): EventRSVP | null {
    return this.communityService.getMyRSVP(this.event);
  }

  get isFull(): boolean {
    return !!this.event.maxParticipants && this.event.participantCount >= this.event.maxParticipants;
  }

  get isPast(): boolean {
    return new Date(this.event.date).getTime() < Date.now();
  }

  /** フィルタ適用後の参加者 */
  get filteredParticipants(): EventParticipant[] {
    const list = this.event.participants;
    if (this.participantsFilter === 'all') return list;
    return list.filter(p => (p.rsvp || 'going') === this.participantsFilter);
  }

  /** 行きます件数 / 未定件数 */
  get goingCount(): number {
    return this.event.participants.filter(p => !p.rsvp || p.rsvp === 'going').length;
  }
  get maybeCount(): number {
    return this.event.participants.filter(p => p.rsvp === 'maybe').length;
  }

  onBack(): void {
    this.back.emit();
  }

  /** 参加ボタン: RSVP 'going' に設定し、参加者モーダルを開く (ユーザー指示 2026-04-21) */
  onJoin(): void {
    this.communityService.setEventRSVP(this.event.id, 'going').subscribe(updated => {
      this.event = updated;
      this.showParticipantsModal = true;
      this.cdr.markForCheck();
    });
  }

  onLeave(): void {
    this.communityService.setEventRSVP(this.event.id, 'declined').subscribe(updated => {
      this.event = updated;
      this.cdr.markForCheck();
    });
  }

  /** 参加者一覧を開く/閉じる (ユーザー指示 2026-04-21) */
  openParticipants(): void {
    this.showParticipantsModal = true;
  }
  closeParticipants(): void {
    this.showParticipantsModal = false;
  }

  /** RSVP 変更 (参加/未定/不参加) */
  setRSVP(rsvp: EventRSVP): void {
    this.communityService.setEventRSVP(this.event.id, rsvp).subscribe(updated => {
      this.event = updated;
      this.cdr.markForCheck();
    });
  }

  rsvpLabel(rsvp?: EventRSVP | null): string {
    switch (rsvp) {
      case 'going': return '参加';
      case 'maybe': return '未定';
      case 'declined': return '不参加';
      default: return '未回答';
    }
  }

  formatDateTime(date: Date): string {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = d.getMonth() + 1;
    const day = d.getDate();
    const weekdays = ['日', '月', '火', '水', '木', '金', '土'];
    const weekday = weekdays[d.getDay()];
    const hours = d.getHours().toString().padStart(2, '0');
    const minutes = d.getMinutes().toString().padStart(2, '0');
    return `${year}年${month}月${day}日（${weekday}）${hours}:${minutes}`;
  }
}
