import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { CommunityMember } from '../../models/community.model';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { RelativeTimePipe } from '../../../../shared/pipes/relative-time.pipe';
import { ChatRequestComponent } from '../chat-request/chat-request.component';

@Component({
  selector: 'app-member-profile',
  standalone: true,
  imports: [CommonModule, MatDialogModule, AvatarComponent, RelativeTimePipe],
  templateUrl: './member-profile.component.html',
  styleUrls: ['./member-profile.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MemberProfileComponent {
  @Input() member!: CommunityMember;
  @Input() isMember = false;
  @Output() close = new EventEmitter<void>();
  @Output() chatRequest = new EventEmitter<CommunityMember>();

  constructor(private dialog: MatDialog) {}

  onClose(): void {
    this.close.emit();
  }

  onChatRequest(): void {
    this.dialog.open(ChatRequestComponent, {
      width: '520px',
      data: {
        type: 'member',
        targetName: this.member.name,
        communityName: ''
      }
    });
  }
}
